import { ChatPromptTemplate, MessagesPlaceholder } from "langchain/prompts";
import { AgentExecutor, createOpenAIToolsAgent } from "langchain/agents";
import { ChatOpenAI } from "@langchain/openai";
import type { BaseMessage } from "langchain/schema";

import { requireOpenAiApiKey } from "../config/env.js";
import { generateDocumentsTool, scanRepositoryTool } from "../tools/index.js";
import { SYSTEM_PROMPT } from "./prompt.js";

export interface AgentConfig {
  model?: string;
  temperature?: number;
  verbose?: boolean;
}

export interface AgentRunOptions {
  input: string;
  history?: BaseMessage[];
  verbose?: boolean;
}

export const createFraIAgentExecutor = async (config: AgentConfig = {}) => {
  requireOpenAiApiKey();

  const llm = new ChatOpenAI({
    modelName: config.model ?? "gpt-4o-mini",
    temperature: config.temperature ?? 0
  });

  const tools = [scanRepositoryTool, generateDocumentsTool];

  const prompt = ChatPromptTemplate.fromMessages([
    ["system", SYSTEM_PROMPT],
    new MessagesPlaceholder("chat_history"),
    ["human", "{input}"],
    new MessagesPlaceholder("agent_scratchpad")
  ]);

  const agent = await createOpenAIToolsAgent({
    llm,
    tools,
    prompt
  });

  return new AgentExecutor({
    agent,
    tools,
    verbose: config.verbose ?? false
  });
};

export const runFraIAgent = async (options: AgentRunOptions) => {
  const executor = await createFraIAgentExecutor();
  return executor.invoke({
    input: options.input,
    chat_history: options.history ?? []
  });
};
import fs from "node:fs";
import path from "node:path";

import { DynamicStructuredTool } from "langchain/tools";
import { z } from "zod";

import { Documents } from "frai-core";

import { resolveWorkingDirectory } from "../config/env.js";

const DOC_FILENAMES = {
  checklist: "checklist.md",
  modelCard: "model_card.md",
  riskFile: "risk_file.md"
} as const;

const parseAnswers = (payload: string) => {
  try {
    const parsed = JSON.parse(payload);
    return parsed;
  } catch (error) {
    throw new Error(
      "Invalid answers payload. Provide a JSON string that matches FRAI questionnaire structure."
    );
  }
};

const schema = z.object({
  answersJson: z
    .string()
    .describe(
      "JSON string containing FRAI questionnaire answers (core, impact, data, performance, monitoring, bias)."
    ),
  outputDir: z
    .string()
    .describe("Optional output directory. Defaults to the current working directory.")
    .optional(),
  overwrite: z
    .boolean()
    .describe("Whether to overwrite existing docs. Defaults to true.")
    .optional()
});

export const generateDocumentsTool = new DynamicStructuredTool({
  name: "generate_responsible_ai_docs",
  description:
    "Create FRAI checklist, model card, and risk file from questionnaire answers. The agent should supply answers as JSON with keys: core, impact, data, performance, monitoring, bias.",
  schema,
  func: async ({ answersJson, outputDir, overwrite }) => {
    const answers = parseAnswers(answersJson);
    const cwd = resolveWorkingDirectory(outputDir);
    const shouldOverwrite = overwrite ?? true;

    const { checklist, modelCard, riskFile } = Documents.generateDocuments({
      answers,
      tips: {}
    });

    const outputs = [
      { name: DOC_FILENAMES.checklist, content: checklist },
      { name: DOC_FILENAMES.modelCard, content: modelCard },
      { name: DOC_FILENAMES.riskFile, content: riskFile }
    ];

    const written: string[] = [];
    const skipped: string[] = [];

    for (const doc of outputs) {
      const targetPath = path.join(cwd, doc.name);
      if (!shouldOverwrite && fs.existsSync(targetPath)) {
        skipped.push(path.relative(process.cwd(), targetPath));
        continue;
