  const {
    root,
    excludedDirs,
    extensions,
    detectors,
    fs: fsModule
  } = config;

  const result = createResult();

  function scanDirectory(dir, isRoot = false) {
    let entries;
    try {
      entries = fsModule.readdirSync(dir, { withFileTypes: true });
    } catch (error) {
      if (isRoot) {
        const reason = error.code === 'ENOENT' ? 'does not exist' : error.code === 'ENOTDIR' ? 'is not a directory' : error.message;
        throw new Error(`Cannot scan ${dir}: ${reason}`);
      }
      console.error(`Error scanning directory ${dir}: ${error.message}`);
      return;
    }

    for (const entry of entries) {
      if (shouldSkip(entry.name, excludedDirs)) continue;

      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        scanDirectory(fullPath);
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name).toLowerCase();
        if (!extensions.includes(ext)) continue;

        result.totalFiles += 1;
        let content;
        try {
          content = fsModule.readFileSync(fullPath, 'utf8');
        } catch (error) {
          console.error(`Error reading file ${fullPath}: ${error.message}`);
          continue;
        }

        for (const detector of detectors) {
          try {
            detector.analyze({
              filePath: fullPath,
              content,
              result,
              config
            });
          } catch (error) {
            console.error(`Detector ${detector.id || 'unknown'} failed on ${fullPath}: ${error.message}`);
          }
        }
      }
    }
  }

  scanDirectory(root);

  return {
    aiFiles: result.aiFiles,
    totalFiles: result.totalFiles,
    aiLibraryMatches: result.aiLibraryMatches,
    aiFunctionMatches: result.aiFunctionMatches
  };
}

export function createScanner(config = {}) {
  return (overrides = {}) => scanCodebase({ ...config, ...overrides });
}

