import { createScanner, scanCodebase } from './index.js';
import { createLibraryDetector } from './detectors.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const EXAMPLES_DIR = path.resolve(__dirname, '../../../../examples');

const withFiles = (files, run) => {
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-scan-'));
  try {
    for (const [name, content] of Object.entries(files)) {
      const target = path.join(tmpDir, name);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, content);
    }
    return run(tmpDir);
  } finally {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
};

const libraryMatchesFor = (files, detectorOptions) =>
  withFiles(files, (root) => {
    const detectors = [createLibraryDetector(detectorOptions)];
    const { aiLibraryMatches } = scanCodebase({ root, detectors });
    return Object.fromEntries(
      Object.entries(aiLibraryMatches).map(([file, libs]) => [path.relative(root, file), libs])
    );
  });

describe('library detection', () => {
  it('detects the OpenAI-backed support triage demo', () => {
    const results = scanCodebase({ root: path.join(EXAMPLES_DIR, 'support-triage-demo') });
    expect(results.aiLibraryMatches[path.join(EXAMPLES_DIR, 'support-triage-demo/src/triage.js')]).toEqual([
      'openai'
    ]);
  });

  it('detects LLM SDKs in every JS/TS import form and module extension', () => {
    const matches = libraryMatchesFor({
      'a.mts': "import Anthropic from '@anthropic-ai/sdk';\nimport { ChatOpenAI } from \"@langchain/openai\";",
      'b.cts': "const OpenAI = require('openai');",
      'c.mjs': "const { ChatAnthropic } = await import('@langchain/anthropic');",
      'd.cjs': "import 'openai/shims/node';",
      'e.ts': "import type { Message } from '@anthropic-ai/sdk/resources';",
      'f.tsx': 'import {\n  ChatPromptTemplate,\n  type BaseMessage\n} from "langchain/prompts";',
      'g.js': "export { OpenAI } from 'openai';\nexport * from '@langchain/core/messages';",
      'h.jsx': "import OpenAI, { toFile } from 'openai'; import 'openai/resources';"
    });

    expect(matches).toEqual({
      'a.mts': ['@anthropic-ai/sdk', '@langchain'],
      'b.cts': ['openai'],
      'c.mjs': ['@langchain'],
      'd.cjs': ['openai'],
      'e.ts': ['@anthropic-ai/sdk'],
      'f.tsx': ['langchain'],
      'g.js': ['openai', '@langchain'],
      'h.jsx': ['openai']
    });
  });

  it('detects Python imports and sub-modules', () => {
    const matches = libraryMatchesFor({
      'a.py': 'import os, anthropic as claude\n',
      'b.py': 'import torch.nn\n',
      'c.py': 'from openai.types import ChatCompletion\n',
      'd.py': 'from langchain.chains import LLMChain\n',
      'e.ipynb': JSON.stringify({
        cells: [
          { cell_type: 'markdown', source: ['import sklearn\n'] },
          { cell_type: 'code', source: ['import numpy as np\n', 'from transformers import pipeline\n'] }
        ]
      })
    });

    expect(matches).toEqual({
      'a.py': ['anthropic'],
      'b.py': ['torch'],
      'c.py': ['openai'],
      'd.py': ['langchain'],
      'e.ipynb': ['transformers']
    });
  });

  it('ignores look-alike modules, relative imports, and commented-out imports', () => {
    const matches = libraryMatchesFor({
      'a.js': "import mock from 'openai-mock';\nimport helper from './openai';\nconst x = require('../anthropic');",
      'b.ts': "// import OpenAI from 'openai';\n/* const a = require('@anthropic-ai/sdk'); */",
      'c.py': '# import openai\nimport caretaker\nfrom .langchain import chain\nfrom torchvision import models\n',
      'd.r': 'library(caretaker)\n# library(caret)\n',
      'e.mjs': "const url = 'https://example.com/openai'; // import 'openai'"
    });

    expect(matches).toEqual({});
  });

  it('reports each library once per file', () => {
    const matches = libraryMatchesFor({
      'a.js': "import OpenAI from 'openai';\nimport 'openai/shims/node';\nconst o = require('openai');\nimport { ChatOpenAI } from '@langchain/openai';\nimport { HumanMessage } from '@langchain/core/messages';"
    });

    expect(matches).toEqual({ 'a.js': ['openai', '@langchain'] });
  });

  it('keeps working with custom library lists', () => {
    const matches = libraryMatchesFor(
      {
        'a.py': 'import pandas as pd\nimport openai\n',
        'b.js': "import { z } from 'zod/v4';"
      },
      ['pandas', 'zod']
    );

    expect(matches).toEqual({ 'a.py': ['pandas'], 'b.js': ['zod'] });
  });
});

describe('scan root', () => {
  it('throws when the directory does not exist', () => {
    expect(() => scanCodebase({ root: path.join(os.tmpdir(), 'frai-missing-dir-does-not-exist') })).toThrow(
      /does not exist/
    );
  });
});

